     4	import type { DashState, LiveEvent, NodeState, TimelineLine, WsMessage } from "./types";
     5	
     6	export const initialState: DashState = {
     7	  nodes: {},
     8	  counters: { active_nodes: 0, threats_detected: 0, filters_deployed: 0, frames_blocked: 0 },
     9	  timeline: [],
    10	  stage: "idle",
    11	  activeNode: null,
    12	  activeAttack: null,
    13	  seq: 0,
    14	};
    15	
    16	const STAGE_BY_TYPE: Partial<Record<LiveEvent["type"], DashState["stage"]>> = {
    17	  ANOMALY_DETECTED: "trigger",
    18	  AGENT_ANALYZING: "agent",
    19	  VERIFYING: "verify",
    20	  OTA_DEPLOYING: "ota",
    21	  DEPLOYED: "done",
    22	};
