    24	function describe(e: LiveEvent): { text: string; tone: TimelineLine["tone"] } {
    25	  const p = e.payload;
    26	  const node = e.node_id ?? "—";
    27	  switch (e.type) {
    28	    case "NODE_UP":
    29	      return { text: `${node} online`, tone: "info" };
    30	    case "NODE_DOWN":
    31	      return { text: `${node} went offline`, tone: "bad" };
    32	    case "ANOMALY_DETECTED":
    33	      return { text: `${node} anomaly — ${p.count ?? "?"} frames in window`, tone: "warn" };
    34	    case "AGENT_ANALYZING":
    35	      return { text: `${node} agent analyzing (attempt ${p.attempt ?? 1})`, tone: "info" };
    36	    case "FILTER_GENERATED":
    37	      return { text: `${node} filter generated — ${p.attack_class ?? "?"}`, tone: "info" };
    38	    case "VERIFYING":
    39	      return { text: `${node} verifying filter (replay test)`, tone: "info" };
    40	    case "VERIFY_FAILED":
    41	      return { text: `${node} verify FAILED ${p.tests ?? ""} (fpr=${p.fpr ?? "?"})`, tone: "bad" };
    42	    case "VERIFY_PASSED":
    43	      return { text: `${node} verify PASSED ${p.tests ?? ""}`, tone: "ok" };
    44	    case "OTA_DEPLOYING":
    45	      return { text: `${node} deploying filter OTA`, tone: "info" };
    46	    case "DEPLOYED":
    47	      return { text: `${node} PROTECTED — ${p.attack_class ?? "filter"} deployed`, tone: "ok" };
    48	    case "FRAME_BLOCKED":
    49	      return { text: `${node} blocked ${p.count ?? 1} attack frames`, tone: "ok" };
    50	    default:
    51	      return { text: e.type, tone: "info" };
    52	  }
    53	}
    54	
    55	function setNodeState(state: DashState, nodeId: string | null, ns: NodeState): DashState["nodes"] {
    56	  if (!nodeId || !state.nodes[nodeId]) return state.nodes;
    57	  return { ...state.nodes, [nodeId]: { ...state.nodes[nodeId], state: ns } };
    58	}
    59	
    60	export function reduce(state: DashState, msg: WsMessage): DashState {
    61	  if (msg.type === "SNAPSHOT") {
    62	    const nodes: DashState["nodes"] = {};
    63	    for (const n of msg.payload.nodes) nodes[n.node_id] = n;
    64	    return { ...state, nodes, counters: msg.payload.counters };
    65	  }
    66	
    67	  const e = msg;
    68	  let nodes = state.nodes;
    69	  const counters = { ...state.counters };
    70	  let activeNode = state.activeNode;
    71	  let activeAttack = state.activeAttack;
    72	
    73	  switch (e.type) {
    74	    case "NODE_UP":
    75	      if (e.node_id && !nodes[e.node_id]) {
    76	        nodes = {
    77	          ...nodes,
    78	          [e.node_id]: {
    79	            node_id: e.node_id,
    80	            state: "NORMAL",
    81	            last_seen: e.ts,
    82	            fw_version: "v1",
    83	            label: e.node_id,
    84	            blocked: 0,
    85	          },
    86	        };
    87	      }
    88	      break;
    89	    case "NODE_DOWN":
    90	      nodes = setNodeState(state, e.node_id, "OFFLINE");
    91	      break;
    92	    case "ANOMALY_DETECTED":
    93	      nodes = setNodeState(state, e.node_id, "ALERT");
    94	      counters.threats_detected += 1;
    95	      activeNode = e.node_id;
    96	      break;
    97	    case "FILTER_GENERATED":
    98	      activeAttack = (e.payload.attack_class as string) ?? activeAttack;
    99	      break;
   100	    case "OTA_DEPLOYING":
   101	      nodes = setNodeState(state, e.node_id, "UPDATING");
   102	      break;
   103	    case "DEPLOYED":
   104	      nodes = setNodeState(state, e.node_id, "PROTECTED");
   105	      counters.filters_deployed += 1;
   106	      break;
   107	    case "FRAME_BLOCKED": {
   108	      const c = Number(e.payload.count ?? 1);
   109	      counters.frames_blocked += c;
   110	      if (e.node_id && nodes[e.node_id]) {
   111	        nodes = {
   112	          ...nodes,
   113	          [e.node_id]: { ...nodes[e.node_id], blocked: nodes[e.node_id].blocked + c },
   114	        };
   115	      }
   116	      break;
   117	    }
   118	    default:
   119	      break;
   120	  }
   121	
   122	  counters.active_nodes = Object.values(nodes).filter((n) => n.state !== "OFFLINE").length;
   123	
   124	  const stage = STAGE_BY_TYPE[e.type] ?? state.stage;
   125	  const { text, tone } = describe(e);
   126	  const line: TimelineLine = { id: state.seq, ts: e.ts, node_id: e.node_id, type: e.type, text, tone };
   127	  const timeline = [line, ...state.timeline].slice(0, 60);
   128	
   129	  return { ...state, nodes, counters, timeline, stage, activeNode, activeAttack, seq: state.seq + 1 };
   130	}
