// Mirror of backend contracts (ARCHITECTURE.md §4). Keep in sync with
// backend/app/models.py — do not diverge without updating both sides.

export type NodeState = "NORMAL" | "ALERT" | "PROTECTED" | "UPDATING" | "OFFLINE";

export type EventType =
  | "NODE_UP"
  | "NODE_DOWN"
  | "ANOMALY_DETECTED"
  | "AGENT_ANALYZING"
  | "FILTER_GENERATED"
  | "VERIFYING"
  | "VERIFY_FAILED"
  | "VERIFY_PASSED"
  | "OTA_DEPLOYING"
  | "DEPLOYED"
  | "FRAME_BLOCKED";

export interface NodeView {
  node_id: string;
  state: NodeState;
  last_seen: number;
  fw_version: string;
  label: string;
  blocked: number;
}

export interface Counters {
  active_nodes: number;
  threats_detected: number;
  filters_deployed: number;
  frames_blocked: number;
}

export interface FleetSnapshot {
  nodes: NodeView[];
  counters: Counters;
}

export interface LiveEvent {
  type: EventType;
  node_id: string | null;
  ts: number;
  payload: Record<string, unknown>;
}

// The bootstrap frame the server sends first on /live.
export interface SnapshotMessage {
  type: "SNAPSHOT";
  payload: FleetSnapshot;
}

export type WsMessage = LiveEvent | SnapshotMessage;

// --- Read-outs narrowed from LiveEvent.payload ---------------------------
// `payload` is free-form on the wire by design (ARCHITECTURE.md §4). The
// reducer narrows it once into the shapes below, so no panel handles `unknown`.

/** What the sniffer sent — the capture the agent is working from. */
export interface AnomalyDetail {
  node_id: string | null;
  ts: number;
  frames: number;
  count: number;
  subtype: number | null;
  frame_type: string;
  window_ms: number;
  rssi: number | null;
  frame_sample: string[];
}

/** The oracle's verdict on one filter. Authoritative; the agent never sets it. */
export interface OracleVerdict {
  passed: boolean;
  tpr: number;
  fpr: number;
  tests_passed: number;
  tests_total: number;
  log: string;
}

/** One pass of write-code → replay-test. A retry appends, never overwrites. */
export interface FilterAttempt {
  attempt: number;
  attack_class: string | null;
  confidence: number | null;
  filter_c_code: string;
  explanation: string;
  verdict: OracleVerdict | null;
}

// Pipeline stages for the loop read-out.
export type Stage = "idle" | "trigger" | "agent" | "verify" | "ota" | "done";

export interface TimelineLine {
  id: number;
  ts: number;
  node_id: string | null;
  type: EventType;
  text: string;
  tone: "info" | "warn" | "ok" | "bad";
}

export interface DashState {
  nodes: Record<string, NodeView>;
  counters: Counters;
  timeline: TimelineLine[];
  stage: Stage;
  activeNode: string | null;
  activeAttack: string | null;
  anomaly: AnomalyDetail | null;
  attempts: FilterAttempt[];
  seq: number;
}

// Pure reducer: folds WS messages into dashboard state. No React, no I/O —
// so it is unit-testable in isolation (see reducer.test.ts).

import type {
  AnomalyDetail,
  DashState,
  FilterAttempt,
  LiveEvent,
  NodeState,
  OracleVerdict,
  TimelineLine,
  WsMessage,
} from "./types";

export const initialState: DashState = {
  nodes: {},
  counters: { active_nodes: 0, threats_detected: 0, filters_deployed: 0, frames_blocked: 0 },
  timeline: [],
  stage: "idle",
  activeNode: null,
  activeAttack: null,
  anomaly: null,
  attempts: [],
  seq: 0,
};

const STAGE_BY_TYPE: Partial<Record<LiveEvent["type"], DashState["stage"]>> = {
  ANOMALY_DETECTED: "trigger",
  AGENT_ANALYZING: "agent",
  VERIFYING: "verify",
  OTA_DEPLOYING: "ota",
  DEPLOYED: "done",
};

// --- payload narrowing ---------------------------------------------------
// The wire type is Record<string, unknown>; every read goes through one of
// these so a missing or malformed key degrades instead of crashing the panel.

function num(payload: LiveEvent["payload"], key: string, fallback: number): number {
  const value = Number(payload[key]);
  return Number.isFinite(value) ? value : fallback;
}

function optNum(payload: LiveEvent["payload"], key: string): number | null {
  const raw = payload[key];
  if (raw === null || raw === undefined || raw === "") return null;
  const value = Number(raw);
  return Number.isFinite(value) ? value : null;
}

function str(payload: LiveEvent["payload"], key: string, fallback = ""): string {
  const raw = payload[key];
  return typeof raw === "string" ? raw : fallback;
}

function optStr(payload: LiveEvent["payload"], key: string): string | null {
  const raw = payload[key];
  return typeof raw === "string" && raw !== "" ? raw : null;
}

function hexList(payload: LiveEvent["payload"], key: string): string[] {
  const raw = payload[key];
  if (!Array.isArray(raw)) return [];
  return raw.filter((frame): frame is string => typeof frame === "string");
}

function readAnomaly(e: LiveEvent): AnomalyDetail {
  return {
    node_id: e.node_id,
    ts: e.ts,
    frames: num(e.payload, "frames", 0),
    count: num(e.payload, "count", 0),
    subtype: optNum(e.payload, "subtype"),
    frame_type: str(e.payload, "frame_type", "mgmt"),
    window_ms: num(e.payload, "window_ms", 1000),
    rssi: optNum(e.payload, "rssi"),
    frame_sample: hexList(e.payload, "frame_sample"),
  };
}

function readAttempt(e: LiveEvent): FilterAttempt {
  return {
    attempt: num(e.payload, "attempt", 1),
    attack_class: optStr(e.payload, "attack_class"),
    confidence: optNum(e.payload, "confidence"),
    filter_c_code: str(e.payload, "filter_c_code"),
    explanation: str(e.payload, "explanation"),
    verdict: null,
  };
}

function readVerdict(e: LiveEvent, passed: boolean): OracleVerdict {
  return {
    passed,
    tpr: num(e.payload, "tpr", 0),
    fpr: num(e.payload, "fpr", 0),
    tests_passed: num(e.payload, "tests_passed", 0),
    tests_total: num(e.payload, "tests_total", 0),
    log: str(e.payload, "log"),
  };
}

/** Attach a verdict to the attempt it judges, keyed by attempt number. */
function withVerdict(attempts: FilterAttempt[], e: LiveEvent, passed: boolean): FilterAttempt[] {
  const attempt = num(e.payload, "attempt", attempts.length);
  const verdict = readVerdict(e, passed);
  const hit = attempts.some((a) => a.attempt === attempt);
  if (!hit) return attempts;
  return attempts.map((a) => (a.attempt === attempt ? { ...a, verdict } : a));
}

// --- timeline text -------------------------------------------------------

function describe(e: LiveEvent): { text: string; tone: TimelineLine["tone"] } {
  const p = e.payload;
  const node = e.node_id ?? "—";
  switch (e.type) {
    case "NODE_UP":
      return { text: `${node} online`, tone: "info" };
    case "NODE_DOWN":
      return { text: `${node} heartbeat lost`, tone: "bad" };
    case "ANOMALY_DETECTED": {
      const a = readAnomaly(e);
      const rssi = a.rssi === null ? "" : `, ${a.rssi} dBm`;
      return {
        text: `${node} ${a.count} ${a.frame_type} frames / ${a.window_ms} ms${rssi}`,
        tone: "warn",
      };
    }
    case "AGENT_ANALYZING":
      return { text: `${node} agent reading capture, attempt ${num(p, "attempt", 1)}`, tone: "info" };
    case "FILTER_GENERATED": {
      const confidence = optNum(p, "confidence");
      const conf = confidence === null ? "" : ` conf ${confidence.toFixed(2)}`;
      return { text: `${node} filter written for ${str(p, "attack_class", "?")}${conf}`, tone: "info" };
    }
    case "VERIFYING":
      return { text: `${node} oracle replaying held-out captures`, tone: "info" };
    case "VERIFY_FAILED":
      return {
        text: `${node} FAIL ${str(p, "tests", "")} tpr ${num(p, "tpr", 0).toFixed(2)} fpr ${num(p, "fpr", 0).toFixed(2)}`,
        tone: "bad",
      };
    case "VERIFY_PASSED":
      return {
        text: `${node} PASS ${str(p, "tests", "")} tpr ${num(p, "tpr", 0).toFixed(2)} fpr ${num(p, "fpr", 0).toFixed(2)}`,
        tone: "ok",
      };
    case "OTA_DEPLOYING":
      return { text: `${node} pushing filter OTA after ${num(p, "attempts", 1)} attempt(s)`, tone: "info" };
    case "DEPLOYED":
      return { text: `${node} protected against ${str(p, "attack_class", "the attack")}`, tone: "ok" };
    case "FRAME_BLOCKED":
      return { text: `${node} dropped ${num(p, "count", 1)} attack frames`, tone: "ok" };
    default:
      return { text: e.type, tone: "info" };
  }
}

function setNodeState(state: DashState, nodeId: string | null, ns: NodeState): DashState["nodes"] {
  if (!nodeId || !state.nodes[nodeId]) return state.nodes;
  return { ...state.nodes, [nodeId]: { ...state.nodes[nodeId], state: ns } };
}

export function reduce(state: DashState, msg: WsMessage): DashState {
  if (msg.type === "SNAPSHOT") {
    const nodes: DashState["nodes"] = {};
    for (const n of msg.payload.nodes) nodes[n.node_id] = n;
    return { ...state, nodes, counters: msg.payload.counters };
  }

  const e = msg;
  let nodes = state.nodes;
  const counters = { ...state.counters };
  let activeNode = state.activeNode;
  let activeAttack = state.activeAttack;
  let anomaly = state.anomaly;
  let attempts = state.attempts;

  switch (e.type) {
    case "NODE_UP":
      if (e.node_id && !nodes[e.node_id]) {
        nodes = {
          ...nodes,
          [e.node_id]: {
            node_id: e.node_id,
            state: "NORMAL",
            last_seen: e.ts,
            fw_version: "v1",
            label: e.node_id,
            blocked: 0,
          },
        };
      }
      break;
    case "NODE_DOWN":
      nodes = setNodeState(state, e.node_id, "OFFLINE");
      break;
    case "ANOMALY_DETECTED":
      nodes = setNodeState(state, e.node_id, "ALERT");
      counters.threats_detected += 1;
      activeNode = e.node_id;
      activeAttack = null;
      anomaly = readAnomaly(e);
      attempts = []; // a new capture starts a fresh write→verify record
      break;
    case "AGENT_ANALYZING":
      break;
    case "FILTER_GENERATED": {
      const next = readAttempt(e);
      activeAttack = next.attack_class ?? activeAttack;
      attempts = [...attempts.filter((a) => a.attempt !== next.attempt), next].sort(
        (a, b) => a.attempt - b.attempt,
      );
      break;
    }
    case "VERIFYING":
      break;
    case "VERIFY_FAILED":
      attempts = withVerdict(attempts, e, false);
      break;
    case "VERIFY_PASSED":
      attempts = withVerdict(attempts, e, true);
      break;
    case "OTA_DEPLOYING":
      nodes = setNodeState(state, e.node_id, "UPDATING");
      break;
    case "DEPLOYED":
      nodes = setNodeState(state, e.node_id, "PROTECTED");
      counters.filters_deployed += 1;
      break;
    case "FRAME_BLOCKED": {
      const c = num(e.payload, "count", 1);
      counters.frames_blocked += c;
      if (e.node_id && nodes[e.node_id]) {
        nodes = {
          ...nodes,
          [e.node_id]: { ...nodes[e.node_id], blocked: nodes[e.node_id].blocked + c },
        };
      }
      break;
    }
    default:
      break;
  }

  counters.active_nodes = Object.values(nodes).filter((n) => n.state !== "OFFLINE").length;

  const stage = STAGE_BY_TYPE[e.type] ?? state.stage;
  const { text, tone } = describe(e);
  const line: TimelineLine = { id: state.seq, ts: e.ts, node_id: e.node_id, type: e.type, text, tone };
  const timeline = [line, ...state.timeline].slice(0, 60);

  return {
    ...state,
    nodes,
    counters,
    timeline,
    stage,
    activeNode,
    activeAttack,
    anomaly,
    attempts,
    seq: state.seq + 1,
  };
}

// Pure read-out helpers for the panel. Kept out of App.tsx so the numbers and
// labels the operator reads are unit-testable (see dashboardView.test.ts).

import type { FilterAttempt, NodeView, Stage, TimelineLine } from "./types";

export function selectFrameFeed(timeline: TimelineLine[], limit: number): TimelineLine[] {
  return timeline.slice(0, Math.max(0, limit));
}

/** Newest attempt — the one whose code is on the bench right now. */
export function currentAttempt(attempts: FilterAttempt[]): FilterAttempt | undefined {
  return attempts.at(-1);
}

/** 802.11 management subtypes the sniffer reports, by their frame-control value. */
const MGMT_SUBTYPES: Record<number, string> = {
  0: "assoc req",
  1: "assoc resp",
  4: "probe req",
  5: "probe resp",
  8: "beacon",
  10: "disassoc",
  11: "auth",
  12: "deauth",
};

export function formatSubtype(subtype: number | null): string {
  if (subtype === null) return "unclassified";
  const hex = `0x${subtype.toString(16).toUpperCase().padStart(2, "0")}`;
  const name = MGMT_SUBTYPES[subtype];
  return name ? `${hex} ${name}` : hex;
}

export interface LoopStep {
  key: Stage;
  label: string;
  /** Which component owns this step — the operator's map of the system. */
  owner: string;
  phase: "past" | "active" | "future";
}

const LOOP: { key: Stage; label: string; owner: string }[] = [
  { key: "trigger", label: "Detect", owner: "sniffer" },
  { key: "agent", label: "Write", owner: "agent" },
  { key: "verify", label: "Replay", owner: "oracle" },
  { key: "ota", label: "Push", owner: "ota" },
  { key: "done", label: "Protect", owner: "fleet" },
];

const STAGE_ORDER: Stage[] = ["idle", "trigger", "agent", "verify", "ota", "done"];

export function selectLoopSteps(stage: Stage): LoopStep[] {
  const active = STAGE_ORDER.indexOf(stage);
  return LOOP.map((step) => {
    const index = STAGE_ORDER.indexOf(step.key);
    return {
      ...step,
      phase: index < active ? "past" : index === active ? "active" : "future",
    };
  });
}

/** Fleet rows, worst state first so an alarm is always at the top of the bay. */
const STATE_RANK: Record<NodeView["state"], number> = {
  ALERT: 0,
  UPDATING: 1,
  OFFLINE: 2,
  PROTECTED: 3,
  NORMAL: 4,
};

export function selectFleetRows(nodes: Record<string, NodeView>): NodeView[] {
  return Object.values(nodes).sort(
    (a, b) => STATE_RANK[a.state] - STATE_RANK[b.state] || a.node_id.localeCompare(b.node_id),
  );
}

/** How the retry loop actually went: one entry per pass, verdict included. */
export interface AttemptTally {
  total: number;
  failed: number;
  /** True once the oracle has cleared one of the attempts. */
  cleared: boolean;
}

export function tallyAttempts(attempts: FilterAttempt[]): AttemptTally {
  return {
    total: attempts.length,
    failed: attempts.filter((a) => a.verdict?.passed === false).length,
    cleared: attempts.some((a) => a.verdict?.passed === true),
  };
}

import "./App.css";

import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { useRef } from "react";

import {
  currentAttempt,
  formatSubtype,
  selectFleetRows,
  selectFrameFeed,
  selectLoopSteps,
  tallyAttempts,
} from "./dashboardView";
import type { AnomalyDetail, Counters, FilterAttempt, NodeView, Stage, TimelineLine } from "./types";
import { useLive } from "./useLive";

gsap.registerPlugin(useGSAP);

const STAGE_CAPTION: Record<Stage, string> = {
  idle: "Listening",
  trigger: "Capture in",
  agent: "Writing filter",
  verify: "Replay test",
  ota: "Pushing OTA",
  done: "Contained",
};

const EVENT_LABEL: Record<TimelineLine["type"], string> = {
  NODE_UP: "up",
  NODE_DOWN: "down",
  ANOMALY_DETECTED: "anomaly",
  AGENT_ANALYZING: "analyze",
  FILTER_GENERATED: "write",
  VERIFYING: "replay",
  VERIFY_FAILED: "fail",
  VERIFY_PASSED: "pass",
  OTA_DEPLOYING: "ota",
  DEPLOYED: "deploy",
  FRAME_BLOCKED: "block",
};

function reducedMotion(): boolean {
  return globalThis.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
}

function formatClock(ts: number): string {
  const ms = ts < 1_000_000_000_000 ? ts * 1000 : ts;
  return new Intl.DateTimeFormat("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).format(new Date(ms));
}

/** Panel digits: full precision, space-grouped, never abbreviated. */
function formatCount(value: number): string {
  return new Intl.NumberFormat("en-US").format(value).replaceAll(",", " ");
}

function Nameplate() {
  return (
    <div className="nameplate">
      <span className="screw" aria-hidden="true" />
      <span className="nameplate-text">
        <strong>SENTINEL</strong>
        <small>autonomous anomaly defense · 802.11 mgmt</small>
      </span>
      <span className="screw" aria-hidden="true" />
    </div>
  );
}

function Gauges({ counters }: { counters: Counters }) {
  const readings: { label: string; value: string }[] = [
    { label: "nodes up", value: formatCount(counters.active_nodes) },
    { label: "threats", value: formatCount(counters.threats_detected) },
    { label: "filters deployed", value: formatCount(counters.filters_deployed) },
    { label: "frames dropped", value: formatCount(counters.frames_blocked) },
  ];
  return (
    <div className="gauges" role="group" aria-label="Fleet totals">
      {readings.map((reading) => (
        <div className="gauge" key={reading.label}>
          <span className="gauge-value">{reading.value}</span>
          <span className="gauge-label">{reading.label}</span>
        </div>
      ))}
    </div>
  );
}

function LinkLamp({ connected }: { connected: boolean }) {
  return (
    <div className="link" data-linked={connected || undefined} role="status">
      <span className="lamp" data-tone={connected ? "ok" : "alarm"} data-blink={!connected || undefined} />
      <span className="link-text">
        <strong>{connected ? "link" : "no link"}</strong>
        <small>{connected ? "ws /live" : "retrying every 1s"}</small>
      </span>
    </div>
  );
}

const LAMP_TONE: Record<NodeView["state"], string> = {
  NORMAL: "idle",
  ALERT: "alarm",
  UPDATING: "busy",
  PROTECTED: "ok",
  OFFLINE: "dead",
};

function FleetBay({ nodes, activeNode }: { nodes: Record<string, NodeView>; activeNode: string | null }) {
  const rows = selectFleetRows(nodes);

  return (
    <section className="bay bay-fleet" aria-labelledby="fleet-legend">
      <h2 className="legend" id="fleet-legend">
        Fleet
        <span className="legend-note">{rows.length} sniffers</span>
      </h2>
      {rows.length === 0 ? (
        <p className="empty">No heartbeat yet. Nodes appear as they report in.</p>
      ) : (
        <ul className="fleet-list">
          {rows.map((node) => (
            <li
              className="fleet-row"
              data-state={node.state.toLowerCase()}
              data-focus={node.node_id === activeNode || undefined}
              key={node.node_id}
            >
              <span
                className="lamp"
                data-tone={LAMP_TONE[node.state]}
                data-blink={node.state === "ALERT" || undefined}
                aria-hidden="true"
              />
              <span className="fleet-id">{node.label}</span>
              <span className="fleet-state">{node.state.toLowerCase()}</span>
              <span className="fleet-meta">
                <span>fw {node.fw_version}</span>
                <span>{formatCount(node.blocked)} dropped</span>
              </span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

function CaptureBay({ anomaly, stage }: { anomaly: AnomalyDetail | null; stage: Stage }) {
  const steps = selectLoopSteps(stage);

  return (
    <section className="bay bay-capture" aria-labelledby="capture-legend">
      <h2 className="legend" id="capture-legend">
        Capture
        <span className="legend-note">{STAGE_CAPTION[stage]}</span>
      </h2>

      {anomaly === null ? (
        <p className="empty">Airspace quiet. The panel fills in when a sniffer flags a window.</p>
      ) : (
        <>
          <dl className="readout">
            <div>
              <dt>source</dt>
              <dd>{anomaly.node_id ?? "—"}</dd>
            </div>
            <div>
              <dt>subtype</dt>
              <dd>{formatSubtype(anomaly.subtype)}</dd>
            </div>
            <div>
              <dt>rate</dt>
              <dd>
                {formatCount(anomaly.count)} {anomaly.frame_type} / {formatCount(anomaly.window_ms)} ms
              </dd>
            </div>
            <div>
              <dt>rssi</dt>
              <dd>{anomaly.rssi === null ? "—" : `${anomaly.rssi} dBm`}</dd>
            </div>
            <div>
              <dt>frames sent</dt>
              <dd>{formatCount(anomaly.frames)}</dd>
            </div>
            <div>
              <dt>logged</dt>
              <dd>
                <time dateTime={new Date(anomaly.ts * 1000).toISOString()}>{formatClock(anomaly.ts)}</time>
              </dd>
            </div>
          </dl>

          {anomaly.frame_sample.length > 0 && (
            <div className="well well-hex">
              <span className="well-tag">raw frames the agent reads</span>
              <ol>
                {anomaly.frame_sample.map((frame, index) => (
                  <li key={frame}>
                    <em>{String(index).padStart(2, "0")}</em>
                    {frame}
                  </li>
                ))}
              </ol>
            </div>
          )}
        </>
      )}

      <ol className="loop" aria-label="Defense loop position">
        {steps.map((step) => (
          <li className="loop-step" data-phase={step.phase} key={step.key}>
            <span className="lamp" data-tone={step.phase === "active" ? "busy" : "idle"} aria-hidden="true" />
            <span className="loop-label">{step.label}</span>
            <span className="loop-owner">{step.owner}</span>
          </li>
        ))}
      </ol>
    </section>
  );
}

function Verdict({ attempt }: { attempt: FilterAttempt }) {
  const verdict = attempt.verdict;
  if (verdict === null) {
    return (
      <div className="verdict" data-pending="true">
        <span className="verdict-wait">oracle replaying held-out captures…</span>
      </div>
    );
  }

  return (
    <div className="verdict" data-passed={verdict.passed || undefined}>
      <dl className="verdict-figures">
        <div>
          <dt>tpr</dt>
          <dd>{verdict.tpr.toFixed(2)}</dd>
        </div>
        <div>
          <dt>fpr</dt>
          <dd>{verdict.fpr.toFixed(2)}</dd>
        </div>
        <div>
          <dt>replays</dt>
          <dd>
            {verdict.tests_passed}/{verdict.tests_total}
          </dd>
        </div>
      </dl>
      <span className="stamp" data-passed={verdict.passed || undefined}>
        {verdict.passed ? "pass" : "fail"}
      </span>
      {!verdict.passed && verdict.log !== "" && (
        <pre className="verdict-log">{verdict.log}</pre>
      )}
    </div>
  );
}

function FilterBay({ attempts }: { attempts: FilterAttempt[] }) {
  const attempt = currentAttempt(attempts);
  const tally = tallyAttempts(attempts);

  return (
    <section className="bay bay-filter" aria-labelledby="filter-legend">
      <h2 className="legend" id="filter-legend">
        Generated filter
        {attempt && (
          <span className="legend-note">
            attempt {attempt.attempt}
            {attempt.attack_class ? ` · ${attempt.attack_class}` : ""}
            {attempt.confidence === null ? "" : ` · conf ${attempt.confidence.toFixed(2)}`}
          </span>
        )}
      </h2>

      {attempt === undefined ? (
        <p className="empty">
          Nothing on the bench. The agent writes a C predicate over frame bytes when a capture lands.
        </p>
      ) : (
        <>
          {attempt.explanation !== "" && <p className="note">{attempt.explanation}</p>}
          <div className="well well-code">
            <span className="well-tag">filter.c</span>
            <pre>{attempt.filter_c_code}</pre>
          </div>
          <Verdict attempt={attempt} />
          {tally.total > 1 && (
            <ol className="attempts" aria-label="Write and replay history">
              {attempts.map((a) => (
                <li key={a.attempt} data-passed={a.verdict?.passed || undefined}>
                  <span>attempt {a.attempt}</span>
                  <span>{a.verdict === null ? "replaying" : `fpr ${a.verdict.fpr.toFixed(2)}`}</span>
                  <span>{a.verdict === null ? "—" : a.verdict.passed ? "pass" : "fail"}</span>
                </li>
              ))}
            </ol>
          )}
        </>
      )}
    </section>
  );
}

function LogBay({ timeline }: { timeline: TimelineLine[] }) {
  const lines = selectFrameFeed(timeline, 40);

  return (
    <section className="bay bay-log" aria-labelledby="log-legend">
      <h2 className="legend" id="log-legend">
        Event log
        <span className="legend-note">newest first</span>
      </h2>
      {lines.length === 0 ? (
        <p className="empty">Waiting on the first event over ws /live.</p>
      ) : (
        <ol className="log" aria-live="polite">
          {lines.map((line) => (
            <li className="log-row" data-tone={line.tone} key={line.id}>
              <time>{formatClock(line.ts)}</time>
              <span className="log-kind">{EVENT_LABEL[line.type]}</span>
              <span className="log-text">{line.text}</span>
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}

export default function App() {
  const { state, connected } = useLive();
  const shellRef = useRef<HTMLDivElement>(null);
  const attempt = currentAttempt(state.attempts);
  const verdictKey = `${attempt?.attempt ?? 0}:${attempt?.verdict?.passed ?? "none"}`;

  useGSAP(
    () => {
      if (reducedMotion()) return;
      gsap.fromTo(
        ".bay",
        { clipPath: "inset(0 0 100% 0)" },
        { clipPath: "inset(0 0 0% 0)", duration: 0.4, stagger: 0.05, ease: "power2.out" },
      );
    },
    { scope: shellRef },
  );

  // A new log line gets one wipe of ink, then settles. No standing animation.
  useGSAP(
    () => {
      if (state.seq === 0 || reducedMotion()) return;
      gsap.fromTo(
        ".log-row:first-child",
        { backgroundColor: "rgba(25, 27, 25, 0.18)" },
        { backgroundColor: "rgba(25, 27, 25, 0)", duration: 0.55, ease: "none" },
      );
    },
    { scope: shellRef, dependencies: [state.seq], revertOnUpdate: true },
  );

  // The verdict stamp lands like it was pressed onto the sheet.
  useGSAP(
    () => {
      if (reducedMotion()) return;
      gsap.fromTo(
        ".stamp",
        { scale: 1.32, rotate: -16, opacity: 0 },
        { scale: 1, rotate: -8, opacity: 1, duration: 0.32, ease: "back.out(2)" },
      );
    },
    { scope: shellRef, dependencies: [verdictKey], revertOnUpdate: true },
  );

  return (
    <div className="hmi" ref={shellRef}>
      <header className="rail">
        <Nameplate />
        <Gauges counters={state.counters} />
        <LinkLamp connected={connected} />
      </header>

      <main className="bays">
        <FleetBay nodes={state.nodes} activeNode={state.activeNode} />
        <CaptureBay anomaly={state.anomaly} stage={state.stage} />
        <FilterBay attempts={state.attempts} />
        <LogBay timeline={state.timeline} />
      </main>
    </div>
  );
}

/* Panel styling follows ISA-101 HMI convention: a low-saturation grey control
   face where colour is spent only on state. An amber lamp means something is
   wrong; nothing decorative is allowed to use the alarm palette. */

:root {
  --panel: #c4c2bb;
  --panel-hi: #d3d1ca;
  --panel-lo: #b0aea7;
  --recess: #a8a6a0;
  --paper: #e7e5de;

  --ink: #191b19;
  --ink-mid: #4e514d;
  --ink-low: #5f625d;
  --engrave: #8b8981;
  --engrave-hi: #dad8d1;

  --lens: #6d6b66;
  --alarm: #a82a17;
  --amber: #b8791a;
  --amber-ink: #7d5210;
  --ok: #256b47;
  --busy: #1d4c76;

  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, "DejaVu Sans Mono", Consolas, monospace;
  --note-face: Georgia, "Times New Roman", serif;

  --gap: 10px;
}

* {
  box-sizing: border-box;
}

:focus-visible {
  outline: 2px solid var(--busy);
  outline-offset: 1px;
}

/* --- shell ------------------------------------------------------------- */

.hmi {
  height: 100dvh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  color: var(--ink);
  background-color: var(--panel);
  /* Brushed anodised face. Barely visible; it stops the grey reading as flat. */
  background-image: repeating-linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.035) 0 1px,
    rgba(0, 0, 0, 0.02) 1px 3px
  );
}

/* --- header rail ------------------------------------------------------- */

.rail {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: 24px;
  padding: 0 var(--gap);
  border-bottom: 1px solid var(--engrave);
  box-shadow: inset 0 -1px 0 var(--engrave-hi);
}

.nameplate {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 14px;
  margin: 8px 0;
  background: linear-gradient(var(--panel-hi), var(--panel-lo));
  border: 1px solid var(--engrave);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

.screw {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, var(--panel-hi), var(--lens));
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.35);
}

.nameplate-text {
  display: grid;
  gap: 1px;
  padding: 7px 0;
}

.nameplate-text strong {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
}

.nameplate-text small,
.legend-note,
.gauge-label,
.well-tag,
.loop-owner,
.link-text small {
  color: var(--ink-mid);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.gauges {
  display: flex;
  align-items: center;
  gap: 1px;
}

.gauge {
  display: grid;
  gap: 2px;
  justify-items: center;
  min-width: 104px;
  padding: 9px 12px;
  background: var(--recess);
  box-shadow:
    inset 1px 1px 0 rgba(0, 0, 0, 0.18),
    inset -1px -1px 0 rgba(255, 255, 255, 0.24);
}

.gauge-value {
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.link {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 12px 0 10px;
  margin: 8px 0;
  border: 1px solid var(--engrave);
  background: var(--panel-lo);
}

.link-text {
  display: grid;
  gap: 1px;
}

.link-text strong {
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.link:not([data-linked]) .link-text strong {
  color: var(--alarm);
}

/* --- annunciator lamps ------------------------------------------------- */

.lamp {
  flex: none;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--lens);
  box-shadow:
    inset 0 0 0 1px rgba(0, 0, 0, 0.45),
    inset 1px 1px 1px rgba(255, 255, 255, 0.3);
}

.lamp[data-tone="alarm"] {
  background: var(--amber);
}

.lamp[data-tone="ok"] {
  background: var(--ok);
}

.lamp[data-tone="busy"] {
  background: var(--busy);
}

.lamp[data-tone="dead"] {
  background: #8f8d87;
}

/* Unacknowledged alarms blink — the convention, not an effect. */
.lamp[data-blink] {
  animation: annunciator 1s steps(1, end) infinite;
}

@keyframes annunciator {
  0%,
  49% {
    background: var(--alarm);
  }
  50%,
  100% {
    background: var(--lens);
  }
}

/* --- bays -------------------------------------------------------------- */

.bays {
  display: grid;
  grid-template-columns: 300px minmax(0, 1fr) 360px;
  grid-template-rows: auto minmax(0, 1fr);
  gap: var(--gap);
  padding: var(--gap);
  min-height: 0;
}

.bay {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 0 11px 11px;
  background: var(--panel);
  border: 1px solid var(--engrave);
  box-shadow:
    inset 1px 1px 0 rgba(255, 255, 255, 0.42),
    inset -1px -1px 0 rgba(0, 0, 0, 0.14);
}

.bay-fleet {
  grid-column: 1;
  grid-row: 1 / span 2;
}

.bay-capture {
  grid-column: 2;
  grid-row: 1;
}

.bay-filter {
  grid-column: 2;
  grid-row: 2;
}

.bay-log {
  grid-column: 3;
  grid-row: 1 / span 2;
}

.legend {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin: 0 -11px 10px;
  padding: 8px 11px;
  border-bottom: 1px solid var(--engrave);
  box-shadow: inset 0 -2px 0 var(--engrave-hi);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.legend-note {
  margin-left: auto;
  font-weight: 400;
}

.empty {
  margin: 0;
  padding: 14px 0;
  color: var(--ink-mid);
  font-size: 11px;
  line-height: 1.6;
}

/* --- fleet ------------------------------------------------------------- */

.fleet-list {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  min-height: 0;
}

.fleet-row {
  display: grid;
  grid-template-columns: 11px 1fr auto;
  align-items: center;
  gap: 4px 8px;
  padding: 8px 8px 8px 7px;
  border-bottom: 1px solid rgba(139, 137, 129, 0.45);
}

.fleet-row[data-focus] {
  background: var(--recess);
  box-shadow: inset 2px 0 0 var(--amber);
}

.fleet-id {
  font-size: 13px;
  font-weight: 600;
}

.fleet-state {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-mid);
}

.fleet-row[data-state="alert"] .fleet-state {
  color: var(--amber-ink);
  font-weight: 700;
}

.fleet-row[data-state="protected"] .fleet-state {
  color: var(--ok);
}

.fleet-row[data-state="updating"] .fleet-state {
  color: var(--busy);
}

.fleet-row[data-state="offline"] {
  color: var(--ink-low);
}

.fleet-meta {
  grid-column: 2 / -1;
  display: flex;
  gap: 12px;
  font-size: 10px;
  color: var(--ink-mid);
}

/* --- capture read-out -------------------------------------------------- */

.readout {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 1px;
  margin: 0 0 var(--gap);
}

.readout > div {
  display: grid;
  gap: 3px;
  padding: 8px 10px;
  background: var(--recess);
  box-shadow:
    inset 1px 1px 0 rgba(0, 0, 0, 0.16),
    inset -1px -1px 0 rgba(255, 255, 255, 0.22);
}

.readout dt {
  color: var(--ink-mid);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.readout dd {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

/* --- wells (recessed data) --------------------------------------------- */

.well {
  position: relative;
  min-height: 0;
  padding: 16px 10px 9px;
  background: var(--recess);
  box-shadow:
    inset 1px 1px 2px rgba(0, 0, 0, 0.22),
    inset -1px -1px 0 rgba(255, 255, 255, 0.2);
}

.well-tag {
  position: absolute;
  top: 4px;
  left: 10px;
}

.well-hex ol {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  max-height: 74px;
  font-size: 11px;
  line-height: 1.7;
  word-break: break-all;
}

.well-hex em {
  margin-right: 9px;
  color: var(--ink-low);
  font-style: normal;
}

.well-code {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--paper);
  box-shadow:
    inset 1px 1px 3px rgba(0, 0, 0, 0.24),
    inset -1px -1px 0 rgba(255, 255, 255, 0.7);
}

.well-code pre {
  margin: 0;
  overflow: auto;
  min-height: 0;
  font-family: var(--mono);
  font-size: 11.5px;
  line-height: 1.62;
  tab-size: 4;
}

/* --- loop position ---------------------------------------------------- */

.loop {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1px;
  margin: auto 0 0;
  padding: 0;
  list-style: none;
}

.loop-step {
  display: grid;
  justify-items: center;
  gap: 4px;
  padding: 9px 4px;
  background: var(--panel-lo);
  box-shadow: inset 1px 1px 0 rgba(255, 255, 255, 0.3);
}

.loop-step[data-phase="past"] {
  background: var(--recess);
}

.loop-step[data-phase="active"] {
  background: var(--panel-hi);
  box-shadow: inset 0 0 0 1px var(--busy);
}

.loop-step[data-phase="future"] {
  color: var(--ink-low);
}

.loop-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* --- generated filter ------------------------------------------------- */

.note {
  margin: 0 0 var(--gap);
  padding-left: 9px;
  border-left: 2px solid var(--engrave);
  color: var(--ink-mid);
  font-family: var(--note-face);
  font-size: 13px;
  font-style: italic;
  line-height: 1.5;
}

.verdict {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-top: var(--gap);
  padding: 9px 11px;
  background: var(--panel-lo);
  border-top: 1px solid var(--engrave);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.verdict-wait,
.verdict-figures dt {
  color: var(--ink-mid);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.verdict-figures {
  display: flex;
  gap: 22px;
  margin: 0;
}

.verdict-figures div {
  display: grid;
  gap: 2px;
}

.verdict-figures dd {
  margin: 0;
  font-size: 17px;
  font-weight: 600;
}

/* The signature: the oracle's verdict pressed onto the sheet. */
.stamp {
  margin-left: auto;
  padding: 3px 12px;
  color: var(--alarm);
  border: 2px double currentcolor;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  transform: rotate(-8deg);
  mix-blend-mode: multiply;
  opacity: 0.86;
}

.stamp[data-passed] {
  color: var(--ok);
}

.verdict-log {
  flex-basis: 100%;
  order: 9;
  margin: 4px 0 0;
  max-height: 62px;
  overflow: auto;
  color: var(--ink-mid);
  font-size: 10.5px;
  line-height: 1.55;
  white-space: pre-wrap;
}

.attempts {
  margin: var(--gap) 0 0;
  padding: 0;
  list-style: none;
  font-size: 10px;
}

.attempts li {
  display: grid;
  grid-template-columns: 1fr auto 54px;
  gap: 10px;
  padding: 5px 0;
  border-top: 1px solid rgba(139, 137, 129, 0.45);
  color: var(--alarm);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.attempts li[data-passed] {
  color: var(--ok);
}

.attempts li span:first-child {
  color: var(--ink-mid);
}

.attempts li span:last-child {
  text-align: right;
  font-weight: 700;
}

/* --- event log -------------------------------------------------------- */

.log {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  min-height: 0;
}

.log-row {
  display: grid;
  grid-template-columns: auto 52px 1fr;
  gap: 9px;
  padding: 5px 4px;
  border-bottom: 1px solid rgba(139, 137, 129, 0.4);
  font-size: 11px;
  line-height: 1.45;
}

.log-row time {
  color: var(--ink-low);
}

.log-kind {
  color: var(--ink-mid);
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding-top: 1px;
}

.log-row[data-tone="warn"] .log-kind {
  color: var(--amber-ink);
  font-weight: 700;
}

.log-row[data-tone="bad"] .log-kind {
  color: var(--alarm);
  font-weight: 700;
}

.log-row[data-tone="ok"] .log-kind {
  color: var(--ok);
}

/* --- narrower panels -------------------------------------------------- */

@media (max-width: 1240px) {
  .bays {
    grid-template-columns: 260px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
  }

  .bay-fleet {
    grid-row: 1 / span 3;
  }

  .bay-log {
    grid-column: 2;
    grid-row: 3;
    max-height: 190px;
  }
}

@media (max-width: 860px) {
  .hmi {
    height: auto;
    min-height: 100dvh;
  }

  .rail {
    flex-wrap: wrap;
    gap: 8px 16px;
  }

  .gauges {
    flex-wrap: wrap;
  }

  .bays {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: none;
  }

  .bay {
    grid-column: 1 !important;
    grid-row: auto !important;
    max-height: none;
  }

  .fleet-list,
  .log {
    overflow: visible;
  }
}

@media (prefers-reduced-motion: reduce) {
  .lamp[data-blink] {
    animation: none;
  }

  .lamp[data-blink] {
    background: var(--alarm);
  }
}

