import { describe, expect, it } from "vitest";

import { initialState, reduce } from "./reducer";
import type { DashState, LiveEvent, SnapshotMessage } from "./types";

function ev(type: LiveEvent["type"], node_id: string | null, payload: Record<string, unknown> = {}): LiveEvent {
  return { type, node_id, ts: 1, payload };
}

const snapshot: SnapshotMessage = {
  type: "SNAPSHOT",
  payload: {
    nodes: [
      { node_id: "esp-01", state: "NORMAL", last_seen: 0, fw_version: "v1", label: "esp-01", blocked: 0 },
    ],
    counters: { active_nodes: 1, threats_detected: 0, filters_deployed: 0, frames_blocked: 0 },
  },
};

/** The loop the backend actually runs: over-broad filter fails, retry passes. */
function runLoop(state: DashState): DashState {
  let s = reduce(state, ev("ANOMALY_DETECTED", "esp-01", { count: 312, subtype: 12, frames: 3 }));
  s = reduce(s, ev("AGENT_ANALYZING", "esp-01", { attempt: 1 }));
  s = reduce(
    s,
    ev("FILTER_GENERATED", "esp-01", {
      attempt: 1,
      attack_class: "deauth_flood",
      confidence: 0.71,
      filter_c_code: "bool block_frame(){return true;}",
      explanation: "block all mgmt",
    }),
  );
  s = reduce(s, ev("VERIFYING", "esp-01", { attempt: 1 }));
  s = reduce(
    s,
    ev("VERIFY_FAILED", "esp-01", {
      attempt: 1,
      tpr: 1,
      fpr: 0.34,
      tests_passed: 4,
      tests_total: 6,
      log: "beacon dropped",
    }),
  );
  s = reduce(s, ev("AGENT_ANALYZING", "esp-01", { attempt: 2 }));
  s = reduce(
    s,
    ev("FILTER_GENERATED", "esp-01", {
      attempt: 2,
      attack_class: "deauth_flood",
      confidence: 0.94,
      filter_c_code: "bool block_frame(){return subtype==0xC;}",
      explanation: "narrowed to deauth/disassoc",
    }),
  );
  return reduce(
    s,
    ev("VERIFY_PASSED", "esp-01", { attempt: 2, tpr: 1, fpr: 0, tests_passed: 6, tests_total: 6 }),
  );
}

describe("reducer", () => {
  it("folds the full loop into node state + counters", () => {
    let s = reduce(initialState, snapshot);
    s = reduce(s, ev("ANOMALY_DETECTED", "esp-01", { count: 200 }));
    expect(s.nodes["esp-01"].state).toBe("ALERT");
    expect(s.counters.threats_detected).toBe(1);

    s = reduce(s, ev("OTA_DEPLOYING", "esp-01"));
    expect(s.nodes["esp-01"].state).toBe("UPDATING");

    s = reduce(s, ev("DEPLOYED", "esp-01", { attack_class: "deauth_flood" }));
    expect(s.nodes["esp-01"].state).toBe("PROTECTED");
    expect(s.counters.filters_deployed).toBe(1);
    expect(s.stage).toBe("done");

    s = reduce(s, ev("FRAME_BLOCKED", "esp-01", { count: 42 }));
    expect(s.counters.frames_blocked).toBe(42);
    expect(s.nodes["esp-01"].blocked).toBe(42);
  });

  it("greys a node on NODE_DOWN and drops active count", () => {
    let s = reduce(initialState, snapshot);
    expect(s.counters.active_nodes).toBe(1);
    s = reduce(s, ev("NODE_DOWN", "esp-01"));
    expect(s.nodes["esp-01"].state).toBe("OFFLINE");
    expect(s.counters.active_nodes).toBe(0);
  });

  it("narrows the capture the sniffer sent", () => {
    const s = reduce(
      reduce(initialState, snapshot),
      ev("ANOMALY_DETECTED", "esp-01", {
        count: 312,
        subtype: 12,
        frames: 3,
        frame_type: "mgmt",
        window_ms: 1000,
        rssi: -54,
        frame_sample: ["c000", "a000", 7],
      }),
    );
    expect(s.anomaly).toMatchObject({ node_id: "esp-01", count: 312, subtype: 12, rssi: -54 });
    expect(s.anomaly?.frame_sample).toEqual(["c000", "a000"]);
  });

  it("defaults a malformed capture payload instead of throwing", () => {
    const s = reduce(
      reduce(initialState, snapshot),
      ev("ANOMALY_DETECTED", "esp-01", { count: "many", subtype: null, frame_sample: "c000" }),
    );
    expect(s.anomaly).toMatchObject({ count: 0, subtype: null, frame_type: "mgmt", window_ms: 1000 });
    expect(s.anomaly?.frame_sample).toEqual([]);
  });

  it("keeps one record per attempt and attaches the oracle's verdict to each", () => {
    const s = runLoop(reduce(initialState, snapshot));

    expect(s.attempts.map((a) => a.attempt)).toEqual([1, 2]);
    expect(s.attempts[0].verdict).toMatchObject({ passed: false, fpr: 0.34, log: "beacon dropped" });
    expect(s.attempts[1].verdict).toMatchObject({ passed: true, fpr: 0, tests_passed: 6 });
    expect(s.attempts[1].filter_c_code).toContain("0xC");
    expect(s.activeAttack).toBe("deauth_flood");
  });

  it("starts a fresh attempt record when the next capture lands", () => {
    let s = runLoop(reduce(initialState, snapshot));
    expect(s.attempts).toHaveLength(2);
    s = reduce(s, ev("ANOMALY_DETECTED", "esp-01", { count: 90 }));
    expect(s.attempts).toEqual([]);
    expect(s.activeAttack).toBeNull();
  });

  it("ignores a verdict for an attempt it never saw generated", () => {
    const s = reduce(reduce(initialState, snapshot), ev("VERIFY_PASSED", "esp-01", { attempt: 7, tpr: 1 }));
    expect(s.attempts).toEqual([]);
  });
});

import { describe, expect, it } from "vitest";

import {
  currentAttempt,
  formatSubtype,
  selectFleetRows,
  selectFrameFeed,
  selectLoopSteps,
  tallyAttempts,
} from "./dashboardView";
import type { FilterAttempt, NodeView, TimelineLine } from "./types";

const timeline: TimelineLine[] = [
  { id: 2, ts: 3, node_id: "esp-01", type: "FRAME_BLOCKED", text: "esp-01 dropped 1240", tone: "ok" },
  { id: 1, ts: 2, node_id: "esp-01", type: "ANOMALY_DETECTED", text: "esp-01 312 mgmt", tone: "warn" },
  { id: 0, ts: 1, node_id: "esp-02", type: "FRAME_BLOCKED", text: "esp-02 dropped 4", tone: "ok" },
];

function node(node_id: string, state: NodeView["state"]): NodeView {
  return { node_id, state, last_seen: 0, fw_version: "v1", label: node_id, blocked: 0 };
}

function attempt(n: number, passed: boolean | null): FilterAttempt {
  return {
    attempt: n,
    attack_class: "deauth_flood",
    confidence: 0.9,
    filter_c_code: "bool block_frame(){}",
    explanation: "",
    verdict:
      passed === null
        ? null
        : { passed, tpr: 1, fpr: passed ? 0 : 0.3, tests_passed: passed ? 6 : 4, tests_total: 6, log: "" },
  };
}

describe("event feed", () => {
  it("caps the feed without mutating its order", () => {
    expect(selectFrameFeed(timeline, 2).map((line) => line.id)).toEqual([2, 1]);
    expect(timeline).toHaveLength(3);
  });
});

describe("subtype read-out", () => {
  it("names the 802.11 management subtypes the sniffer reports", () => {
    expect(formatSubtype(12)).toBe("0x0C deauth");
    expect(formatSubtype(10)).toBe("0x0A disassoc");
    expect(formatSubtype(8)).toBe("0x08 beacon");
  });

  it("still shows the hex for a subtype it has no name for", () => {
    expect(formatSubtype(9)).toBe("0x09");
    expect(formatSubtype(null)).toBe("unclassified");
  });
});

describe("loop position", () => {
  it("splits the loop into done, running and not-yet", () => {
    const steps = selectLoopSteps("verify");
    expect(steps.map((s) => s.phase)).toEqual(["past", "past", "active", "future", "future"]);
    expect(steps.map((s) => s.owner)).toEqual(["sniffer", "agent", "oracle", "ota", "fleet"]);
  });

  it("marks nothing active while idle", () => {
    expect(selectLoopSteps("idle").every((s) => s.phase === "future")).toBe(true);
  });
});

describe("fleet ordering", () => {
  it("floats alarms to the top of the bay and settles the rest by id", () => {
    const rows = selectFleetRows({
      "esp-03": node("esp-03", "NORMAL"),
      "esp-01": node("esp-01", "PROTECTED"),
      "esp-02": node("esp-02", "ALERT"),
      "esp-04": node("esp-04", "OFFLINE"),
      "esp-05": node("esp-05", "UPDATING"),
    });
    expect(rows.map((r) => r.node_id)).toEqual(["esp-02", "esp-05", "esp-04", "esp-01", "esp-03"]);
  });
});

describe("attempt history", () => {
  it("reports the retry count and whether the oracle ever cleared a filter", () => {
    expect(tallyAttempts([attempt(1, false), attempt(2, true)])).toEqual({
      total: 2,
      failed: 1,
      cleared: true,
    });
    expect(tallyAttempts([attempt(1, false), attempt(2, null)])).toEqual({
      total: 2,
      failed: 1,
      cleared: false,
    });
    expect(tallyAttempts([])).toEqual({ total: 0, failed: 0, cleared: false });
  });

  it("puts the newest attempt on the bench", () => {
    expect(currentAttempt([attempt(1, false), attempt(2, null)])?.attempt).toBe(2);
    expect(currentAttempt([])).toBeUndefined();
  });
});

