import "./App.css";

import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { useEffect, useMemo, useRef } from "react";

import {
  currentAttempt,
  formatSubtype,
  selectFleetRows,
  selectFrameFeed,
  selectLoopSteps,
  tallyAttempts,
} from "./dashboardView";
import type { AnomalyDetail, Counters, FilterAttempt, NodeView, Stage, TimelineLine } from "./types";
import { useLive } from "./useLive";

gsap.registerPlugin(useGSAP);

const STAGE_CAPTION: Record<Stage, string> = {
  idle: "Listening",
  trigger: "Capture in",
  agent: "Writing filter",
  verify: "Replay test",
  ota: "Pushing OTA",
  done: "Contained",
};

const EVENT_LABEL: Record<TimelineLine["type"], string> = {
  NODE_UP: "up",
  NODE_DOWN: "down",
  ANOMALY_DETECTED: "anomaly",
  AGENT_ANALYZING: "analyze",
  FILTER_GENERATED: "write",
  VERIFYING: "replay",
  VERIFY_FAILED: "fail",
  VERIFY_PASSED: "pass",
  OTA_DEPLOYING: "ota",
  DEPLOYED: "deploy",
  FRAME_BLOCKED: "block",
};

function reducedMotion(): boolean {
  return globalThis.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
}

function formatClock(ts: number): string {
  const ms = ts < 1_000_000_000_000 ? ts * 1000 : ts;
  return new Intl.DateTimeFormat("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).format(new Date(ms));
}

function formatCount(value: number): string {
  return new Intl.NumberFormat("en-US").format(value).replaceAll(",", " ");
}

/** attack_class is a machine token; the headline wants it as words. */
function titleCase(value: string): string {
  return value.replaceAll("_", " ");
}

function Wordmark() {
  return (
    <div className="wordmark">
      <span className="wordmark-dot" aria-hidden="true" />
      <span>
        <strong>Sentinel</strong>
        <small>autonomous defense</small>
      </span>
    </div>
  );
}

function HeaderCounters({ counters }: { counters: Counters }) {
  const readings: { label: string; value: string }[] = [
    { label: "nodes", value: formatCount(counters.active_nodes) },
    { label: "threats", value: formatCount(counters.threats_detected) },
    { label: "filters", value: formatCount(counters.filters_deployed) },
    { label: "frames dropped", value: formatCount(counters.frames_blocked) },
  ];
  return (
    <div className="counters" role="group" aria-label="Fleet totals">
      {readings.map((reading) => (
        <div key={reading.label}>
          <strong>{reading.value}</strong>
          <span>{reading.label}</span>
        </div>
      ))}
    </div>
  );
}

function LinkPill({ connected }: { connected: boolean }) {
  return (
    <div className="link-pill" data-linked={connected || undefined} role="status">
      <i aria-hidden="true" />
      {connected ? "live" : "reconnecting"}
    </div>
  );
}

function FleetPanel({ nodes, activeNode }: { nodes: Record<string, NodeView>; activeNode: string | null }) {
  const rows = selectFleetRows(nodes);

  return (
    <section className="panel panel-fleet" aria-labelledby="fleet-title">
      <header className="panel-head">
        <h2 id="fleet-title">Fleet</h2>
        <span>{rows.length} sniffers</span>
      </header>
      {rows.length === 0 ? (
        <p className="blank">No heartbeat yet. Nodes join the list as they report in.</p>
      ) : (
        <ul className="fleet">
          {rows.map((node) => (
            <li
              className="node"
              data-state={node.state.toLowerCase()}
              data-focus={node.node_id === activeNode || undefined}
              key={node.node_id}
            >
              <span className="node-dot" aria-hidden="true" />
              <span className="node-id">{node.label}</span>
              <span className="node-state">{node.state.toLowerCase()}</span>
              <span className="node-meta">
                fw {node.fw_version} · {formatCount(node.blocked)} dropped
              </span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

function Capture({ anomaly, stage }: { anomaly: AnomalyDetail | null; stage: Stage }) {
  if (anomaly === null) {
    return (
      <div className="capture capture-idle">
        <span className="eyebrow">{STAGE_CAPTION[stage]}</span>
        <h1>Airspace clear</h1>
        <p className="dek">No sniffer has flagged a window. The loop starts on its own when one does.</p>
      </div>
    );
  }

  const facts: { label: string; value: string }[] = [
    { label: "subtype", value: formatSubtype(anomaly.subtype) },
    {
      label: "rate",
      value: `${formatCount(anomaly.count)} ${anomaly.frame_type} / ${formatCount(anomaly.window_ms)} ms`,
    },
    { label: "rssi", value: anomaly.rssi === null ? "—" : `${anomaly.rssi} dBm` },
    { label: "capture", value: `${formatCount(anomaly.frames)} frames` },
  ];

  return (
    <div className="capture">
      <span className="eyebrow">
        {anomaly.node_id ?? "unknown node"} · <time>{formatClock(anomaly.ts)}</time> · {STAGE_CAPTION[stage]}
      </span>
      <h1>{titleCase("deauth burst")}</h1>
      <dl className="facts">
        {facts.map((fact) => (
          <div key={fact.label}>
            <dt>{fact.label}</dt>
            <dd>{fact.value}</dd>
          </div>
        ))}
      </dl>
      {anomaly.frame_sample.length > 0 && (
        <div className="evidence">
          <span className="evidence-tag">raw frames the agent reads</span>
          <ol>
            {anomaly.frame_sample.map((frame) => (
              <li key={frame}>{frame}</li>
            ))}
          </ol>
        </div>
      )}
    </div>
  );
}

function LoopRail({ stage }: { stage: Stage }) {
  const steps = selectLoopSteps(stage);
  return (
    <ol className="rail" aria-label="Defense loop position">
      {steps.map((step) => (
        <li className="rail-step" data-phase={step.phase} key={step.key}>
          <span className="rail-dot" aria-hidden="true" />
          <span className="rail-label">{step.label}</span>
          <span className="rail-owner">{step.owner}</span>
        </li>
      ))}
    </ol>
  );
}

/** Comment and preprocessor lines recede so the predicate carries the panel. */
function lineKind(line: string): "comment" | "pre" | "code" {
  const trimmed = line.trimStart();
  if (trimmed.startsWith("/*") || trimmed.startsWith("*") || trimmed.startsWith("//")) return "comment";
  if (trimmed.startsWith("#")) return "pre";
  return "code";
}

function CodePanel({ code }: { code: string }) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const lines = useMemo(() => code.split("\n"), [code]);

  useEffect(() => {
    const box = scrollRef.current;
    if (box === null) return;
    const target = lines.findIndex((line) => line.includes("block_frame("));
    const lineHeight = box.scrollHeight / Math.max(lines.length, 1);
    // Only scroll if the predicate sits below the fold.
    const inView = (target + 1) * lineHeight <= box.clientHeight;
    box.scrollTop = target <= 0 || inView ? 0 : Math.max(0, (target - 1) * lineHeight);
  }, [lines]);

  useGSAP(
    () => {
      if (reducedMotion()) return;
      gsap.fromTo(
        ".code-line",
        { opacity: 0, x: -6 },
        { opacity: 1, x: 0, duration: 0.18, stagger: 0.012, ease: "none" },
      );
    },
    { scope: scrollRef, dependencies: [code], revertOnUpdate: true },
  );

  return (
    <div className="code-wrap">
      <span className="code-tag">filter.c</span>
      <div className="code" ref={scrollRef}>
        {lines.map((line, index) => (
          <span className="code-line" data-kind={lineKind(line)} key={`${index}-${line}`}>
            {line === "" ? " " : line}
          </span>
        ))}
      </div>
    </div>
  );
}

function VerdictRow({ attempt }: { attempt: FilterAttempt }) {
  const verdict = attempt.verdict;

  if (verdict === null) {
    return (
      <div className="verdict" data-pending="true">
        <span className="verdict-pending">Oracle replaying held-out captures</span>
      </div>
    );
  }

  return (
    <div className="verdict" data-passed={verdict.passed || undefined}>
      <dl>
        <div>
          <dt>tpr</dt>
          <dd>{verdict.tpr.toFixed(2)}</dd>
        </div>
        <div>
          <dt>fpr</dt>
          <dd>{verdict.fpr.toFixed(2)}</dd>
        </div>
        <div>
          <dt>replays</dt>
          <dd>
            {verdict.tests_passed}/{verdict.tests_total}
          </dd>
        </div>
      </dl>
      <span className="badge">{verdict.passed ? "pass" : "fail"}</span>
      {!verdict.passed && verdict.log !== "" && <pre className="verdict-log">{verdict.log}</pre>}
    </div>
  );
}

function FilterPanel({ attempts }: { attempts: FilterAttempt[] }) {
  const attempt = currentAttempt(attempts);
  const tally = tallyAttempts(attempts);

  return (
    <section className="panel panel-filter" aria-labelledby="filter-title">
      <header className="panel-head">
        <h2 id="filter-title">Generated filter</h2>
        {attempt && (
          <span>
            attempt {attempt.attempt}
            {attempt.attack_class ? ` · ${attempt.attack_class}` : ""}
            {attempt.confidence === null ? "" : ` · conf ${attempt.confidence.toFixed(2)}`}
          </span>
        )}
      </header>

      {attempt === undefined ? (
        <p className="blank">
          Nothing on the bench. When a capture lands, the agent writes a C predicate over the frame bytes
          and the oracle replays it before anything ships.
        </p>
      ) : (
        <>
          {attempt.explanation !== "" && <p className="rationale">{attempt.explanation}</p>}
          <CodePanel code={attempt.filter_c_code} />
          <VerdictRow attempt={attempt} />
          {tally.total > 1 && (
            <ol className="attempts" aria-label="Write and replay history">
              {attempts.map((a) => (
                <li key={a.attempt} data-passed={a.verdict?.passed || undefined}>
                  <span>attempt {a.attempt}</span>
                  <span>{a.verdict === null ? "replaying" : `fpr ${a.verdict.fpr.toFixed(2)}`}</span>
                  <span>{a.verdict === null ? "—" : a.verdict.passed ? "pass" : "fail"}</span>
                </li>
              ))}
            </ol>
          )}
        </>
      )}
    </section>
  );
}

function EventLog({ timeline }: { timeline: TimelineLine[] }) {
  const lines = selectFrameFeed(timeline, 40);

  return (
    <section className="panel panel-log" aria-labelledby="log-title">
      <header className="panel-head">
        <h2 id="log-title">Event log</h2>
        <span>newest first</span>
      </header>
      {lines.length === 0 ? (
        <p className="blank">Waiting on the first event over ws /live.</p>
      ) : (
        <ol className="log" aria-live="polite">
          {lines.map((line) => (
            <li className="log-row" data-tone={line.tone} key={line.id}>
              <time>{formatClock(line.ts)}</time>
              <span className="log-kind">{EVENT_LABEL[line.type]}</span>
              <span>{line.text}</span>
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}

export default function App() {
  const { state, connected } = useLive();
  const shellRef = useRef<HTMLDivElement>(null);
  const attempt = currentAttempt(state.attempts);
  const verdictKey = `${attempt?.attempt ?? 0}:${attempt?.verdict?.passed ?? "none"}`;

  useGSAP(
