  useGSAP(
    () => {
      if (reducedMotion()) return;
      gsap.fromTo(
        ".badge",
        { scale: 0.86, opacity: 0 },
        { scale: 1, opacity: 1, duration: 0.34, ease: "back.out(2.2)" },
      );
    },
    { scope: shellRef, dependencies: [verdictKey], revertOnUpdate: true },
  );

  useGSAP(
    () => {
      if (state.seq === 0 || reducedMotion()) return;
      gsap.fromTo(
        ".log-row:first-child",
        { opacity: 0, x: 10 },
        { opacity: 1, x: 0, duration: 0.35, ease: "power2.out" },
      );
    },
    { scope: shellRef, dependencies: [state.seq], revertOnUpdate: true },
  );

  return (
    <div className="shell" ref={shellRef}>
      <header className="topbar">
        <Wordmark />
        <HeaderCounters counters={state.counters} />
        <LinkPill connected={connected} />
      </header>

      <main className="stage">
        <FleetPanel nodes={state.nodes} activeNode={state.activeNode} />
        <div className="lane">
          <Capture anomaly={state.anomaly} stage={state.stage} />
          <LoopRail stage={state.stage} />
          <FilterPanel attempts={state.attempts} />
        </div>
        <EventLog timeline={state.timeline} />
      </main>
    </div>
  );
}

