import "./App.css";

import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { useEffect, useMemo, useRef } from "react";

import {
  currentAttempt,
  formatSubtype,
  selectFleetRows,
  selectFrameFeed,
  selectLoopSteps,
  tallyAttempts,
} from "./dashboardView";
import type { AnomalyDetail, Counters, FilterAttempt, NodeView, Stage, TimelineLine } from "./types";
import { useLive } from "./useLive";

gsap.registerPlugin(useGSAP);

const STAGE_CAPTION: Record<Stage, string> = {
  idle: "Listening",
  trigger: "Capture in",
  agent: "Writing filter",
  verify: "Replay test",
  ota: "Pushing OTA",
  done: "Contained",
};

const EVENT_LABEL: Record<TimelineLine["type"], string> = {
  NODE_UP: "up",
  NODE_DOWN: "down",
  ANOMALY_DETECTED: "anomaly",
  AGENT_ANALYZING: "analyze",
  FILTER_GENERATED: "write",
  VERIFYING: "replay",
  VERIFY_FAILED: "fail",
  VERIFY_PASSED: "pass",
  OTA_DEPLOYING: "ota",
  DEPLOYED: "deploy",
  FRAME_BLOCKED: "block",
};

function reducedMotion(): boolean {
  return globalThis.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
}

function formatClock(ts: number): string {
  const ms = ts < 1_000_000_000_000 ? ts * 1000 : ts;
  return new Intl.DateTimeFormat("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).format(new Date(ms));
}

function formatCount(value: number): string {
  return new Intl.NumberFormat("en-US").format(value).replaceAll(",", " ");
}

/**
 * The headline. `attack_class` is the agent's own classification and only
 * exists once it has written a filter, so until then the capture is named by
 * what the sniffer could actually tell — its frame subtype.
 */
function headline(attack: string | null, anomaly: AnomalyDetail): string {
  if (attack !== null) return attack.replaceAll("_", " ");
  const subtype = formatSubtype(anomaly.subtype);
  return subtype === "unclassified" ? "Unclassified burst" : `${subtype.split(" ").at(-1)} burst`;
}

function Wordmark() {
  return (
    <div className="wordmark">
      <span className="wordmark-dot" aria-hidden="true" />
      <span>
        <strong>Sentinel</strong>
        <small>autonomous defense</small>
      </span>
    </div>
  );
}

function HeaderCounters({ counters }: { counters: Counters }) {
  const readings: { label: string; value: string }[] = [
    { label: "nodes", value: formatCount(counters.active_nodes) },
    { label: "threats", value: formatCount(counters.threats_detected) },
    { label: "filters", value: formatCount(counters.filters_deployed) },
    { label: "frames dropped", value: formatCount(counters.frames_blocked) },
  ];
  return (
    <div className="counters" role="group" aria-label="Fleet totals">
      {readings.map((reading) => (
        <div key={reading.label}>
          <strong>{reading.value}</strong>
          <span>{reading.label}</span>
        </div>
      ))}
    </div>
  );
}

function LinkPill({ connected }: { connected: boolean }) {
  return (
    <div className="link-pill" data-linked={connected || undefined} role="status">
      <i aria-hidden="true" />
      {connected ? "live" : "reconnecting"}
    </div>
  );
}

function FleetPanel({ nodes, activeNode }: { nodes: Record<string, NodeView>; activeNode: string | null }) {
  const rows = selectFleetRows(nodes);

  return (
    <section className="panel panel-fleet" aria-labelledby="fleet-title">
      <header className="panel-head">
        <h2 id="fleet-title">Fleet</h2>
        <span>{rows.length} sniffers</span>
      </header>
      {rows.length === 0 ? (
        <p className="blank">No heartbeat yet. Nodes join the list as they report in.</p>
      ) : (
        <ul className="fleet">
          {rows.map((node) => (
            <li
              className="node"
              data-state={node.state.toLowerCase()}
              data-focus={node.node_id === activeNode || undefined}
              key={node.node_id}
            >
              <span className="node-dot" aria-hidden="true" />
              <span className="node-id">{node.label}</span>
              <span className="node-state">{node.state.toLowerCase()}</span>
              <span className="node-meta">
                fw {node.fw_version} · {formatCount(node.blocked)} dropped
              </span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

function Capture({
  anomaly,
  attack,
  stage,
}: {
  anomaly: AnomalyDetail | null;
  attack: string | null;
  stage: Stage;
}) {
  if (anomaly === null) {
    return (
      <div className="capture">
        <span className="eyebrow">{STAGE_CAPTION[stage]}</span>
        <h1>Airspace clear</h1>
        <p className="dek">No sniffer has flagged a window. The loop starts on its own when one does.</p>
      </div>
    );
  }

  const facts: { label: string; value: string }[] = [
    { label: "subtype", value: formatSubtype(anomaly.subtype) },
    {
      label: "rate",
      value: `${formatCount(anomaly.count)} ${anomaly.frame_type} / ${formatCount(anomaly.window_ms)} ms`,
    },
    { label: "rssi", value: anomaly.rssi === null ? "—" : `${anomaly.rssi} dBm` },
    { label: "capture", value: `${formatCount(anomaly.frames)} frames` },
  ];

  return (
    <div className="capture">
      <span className="eyebrow">
        {anomaly.node_id ?? "unknown node"} · <time>{formatClock(anomaly.ts)}</time> ·{" "}
        {STAGE_CAPTION[stage]}
      </span>
      <h1>{headline(attack, anomaly)}</h1>
      <dl className="facts">
        {facts.map((fact) => (
          <div key={fact.label}>
            <dt>{fact.label}</dt>
            <dd>{fact.value}</dd>
          </div>
        ))}
      </dl>
      {anomaly.frame_sample.length > 0 && (
        <div className="evidence">
          <span className="evidence-tag">raw frames the agent reads</span>
          <ol>
            {anomaly.frame_sample.map((frame) => (
              <li key={frame}>{frame}</li>
            ))}
          </ol>
        </div>
      )}
    </div>
  );
}

function LoopRail({ stage }: { stage: Stage }) {
  const steps = selectLoopSteps(stage);
  return (
    <ol className="rail" aria-label="Defense loop position">
      {steps.map((step) => (
        <li className="rail-step" data-phase={step.phase} key={step.key}>
          <span className="rail-dot" aria-hidden="true" />
          <span className="rail-label">{step.label}</span>
          <span className="rail-owner">{step.owner}</span>
        </li>
      ))}
    </ol>
  );
}

/** Comments and includes recede so the predicate carries the panel. */
function lineKind(line: string): "comment" | "pre" | "code" {
  const trimmed = line.trimStart();
  if (trimmed.startsWith("/*") || trimmed.startsWith("*") || trimmed.startsWith("//")) return "comment";
  if (trimmed.startsWith("#")) return "pre";
  return "code";
}

function CodePanel({ code }: { code: string }) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const lines = useMemo(() => code.split("\n"), [code]);

  useEffect(() => {
    const box = scrollRef.current;
    if (box === null) return;
    const target = lines.findIndex((line) => line.includes("block_frame("));
    const lineHeight = box.scrollHeight / Math.max(lines.length, 1);
    // Only scroll when the predicate sits below the fold.
    const inView = (target + 1) * lineHeight <= box.clientHeight;
    box.scrollTop = target <= 0 || inView ? 0 : Math.max(0, (target - 1) * lineHeight);
  }, [lines]);

  // The agent wrote this a second ago; the lines land in the order it wrote them.
  useGSAP(
    () => {
      if (reducedMotion()) return;
      gsap.fromTo(
        ".code-line",
        { opacity: 0, x: -6 },
        { opacity: 1, x: 0, duration: 0.18, stagger: 0.012, ease: "none" },
      );
    },
    { scope: scrollRef, dependencies: [code], revertOnUpdate: true },
  );

  return (
    <div className="code-wrap">
      <span className="code-tag">filter.c</span>
      <div className="code" ref={scrollRef}>
        {lines.map((line, index) => (
          <span className="code-line" data-kind={lineKind(line)} key={`${index}-${line}`}>
            {line === "" ? " " : line}
          </span>
        ))}
      </div>
    </div>
  );
}

function VerdictRow({ attempt }: { attempt: FilterAttempt }) {
  const verdict = attempt.verdict;

  if (verdict === null) {
    return (
      <div className="verdict">
        <span className="verdict-pending">Oracle replaying held-out captures</span>
      </div>
    );
  }

  return (
    <div className="verdict" data-passed={verdict.passed || undefined}>
      <dl>
        <div>
          <dt>tpr</dt>
          <dd>{verdict.tpr.toFixed(2)}</dd>
        </div>
        <div>
          <dt>fpr</dt>
          <dd>{verdict.fpr.toFixed(2)}</dd>
        </div>
        <div>
          <dt>replays</dt>
          <dd>
            {verdict.tests_passed}/{verdict.tests_total}
          </dd>
        </div>
      </dl>
      <span className="badge">{verdict.passed ? "pass" : "fail"}</span>
      {!verdict.passed && verdict.log !== "" && <pre className="verdict-log">{verdict.log}</pre>}
    </div>
  );
}

function FilterPanel({ attempts }: { attempts: FilterAttempt[] }) {
  const attempt = currentAttempt(attempts);
  const tally = tallyAttempts(attempts);

  return (
    <section className="panel panel-filter" aria-labelledby="filter-title">
      <header className="panel-head">
        <h2 id="filter-title">Generated filter</h2>
        {attempt && (
          <span>
            attempt {attempt.attempt}
            {attempt.attack_class ? ` · ${attempt.attack_class}` : ""}
            {attempt.confidence === null ? "" : ` · conf ${attempt.confidence.toFixed(2)}`}
          </span>
        )}
      </header>

      {attempt === undefined ? (
        <p className="blank">
          Nothing on the bench. When a capture lands, the agent writes a C predicate over the frame bytes
          and the oracle replays it before anything ships.
        </p>
      ) : (
        <>
          {attempt.explanation !== "" && <p className="rationale">{attempt.explanation}</p>}
          <CodePanel code={attempt.filter_c_code} />
          <VerdictRow attempt={attempt} />
          {tally.total > 1 && (
            <ol className="attempts" aria-label="Write and replay history">
              {attempts.map((a) => (
                <li key={a.attempt} data-passed={a.verdict?.passed || undefined}>
                  <span>attempt {a.attempt}</span>
                  <span>{a.verdict === null ? "replaying" : `fpr ${a.verdict.fpr.toFixed(2)}`}</span>
                  <span>{a.verdict === null ? "—" : a.verdict.passed ? "pass" : "fail"}</span>
                </li>
              ))}
            </ol>
          )}
        </>
      )}
    </section>
  );
}

function EventLog({ timeline }: { timeline: TimelineLine[] }) {
  const lines = selectFrameFeed(timeline, 40);

  return (
    <section className="panel panel-log" aria-labelledby="log-title">
      <header className="panel-head">
        <h2 id="log-title">Event log</h2>
        <span>newest first</span>
      </header>
      {lines.length === 0 ? (
        <p className="blank">Waiting on the first event over ws /live.</p>
      ) : (
        <ol className="log" aria-live="polite">
          {lines.map((line) => (
            <li className="log-row" data-tone={line.tone} key={line.id}>
              <time>{formatClock(line.ts)}</time>
              <span className="log-kind">{EVENT_LABEL[line.type]}</span>
              <span>{line.text}</span>
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}

export default function App() {
  const { state, connected } = useLive();
  const shellRef = useRef<HTMLDivElement>(null);
  const attempt = currentAttempt(state.attempts);
  const verdictKey = `${attempt?.attempt ?? 0}:${attempt?.verdict?.passed ?? "none"}`;

  useGSAP(
    () => {
      if (reducedMotion()) return;
      gsap.fromTo(
        ".panel, .capture",
        { opacity: 0, y: 14 },
        { opacity: 1, y: 0, duration: 0.6, stagger: 0.07, ease: "power3.out" },
      );
    },
    { scope: shellRef },
  );

  useGSAP(
    () => {
      if (reducedMotion()) return;
      gsap.fromTo(
        ".capture > *",
        { opacity: 0, y: 10 },
        { opacity: 1, y: 0, duration: 0.45, stagger: 0.05, ease: "power2.out" },
      );
    },
    { scope: shellRef, dependencies: [state.anomaly?.ts ?? 0], revertOnUpdate: true },
  );

  useGSAP(
    () => {
      if (reducedMotion()) return;
      gsap.fromTo(
        ".badge",
        { scale: 0.86, opacity: 0 },
        { scale: 1, opacity: 1, duration: 0.34, ease: "back.out(2.2)" },
      );
    },
    { scope: shellRef, dependencies: [verdictKey], revertOnUpdate: true },
  );

  useGSAP(
    () => {
      if (state.seq === 0 || reducedMotion()) return;
      gsap.fromTo(
        ".log-row:first-child",
        { opacity: 0, x: 10 },
        { opacity: 1, x: 0, duration: 0.35, ease: "power2.out" },
      );
    },
    { scope: shellRef, dependencies: [state.seq], revertOnUpdate: true },
  );

  return (
    <div className="shell" ref={shellRef}>
      <header className="topbar">
        <Wordmark />
        <HeaderCounters counters={state.counters} />
        <LinkPill connected={connected} />
      </header>

      <main className="stage">
        <FleetPanel nodes={state.nodes} activeNode={state.activeNode} />
        <div className="lane">
          <Capture anomaly={state.anomaly} attack={state.activeAttack} stage={state.stage} />
          <LoopRail stage={state.stage} />
          <FilterPanel attempts={state.attempts} />
        </div>
        <EventLog timeline={state.timeline} />
      </main>
    </div>
  );
}

/* Dark ground, ember for heat, steel for work in progress, jade for cleared.
   Glow is spent only where state changes; the code panel is the hero and
   everything around it stays quiet. */

:root {
  --ground: #0b0c0f;
  --raise: #14161b;
  --raise-2: #1a1d24;
  --sunk: #070809;

  --line: rgba(228, 231, 240, 0.07);
  --line-2: rgba(228, 231, 240, 0.14);

  --text: #e8eaf0;
  --dim: #99a0ae;
  --faint: #666d7b;

  --ember: #e0653a;
  --ember-dim: rgba(224, 101, 58, 0.14);
  --steel: #7fa8c4;
  --jade: #45b98d;
  --crimson: #ef5350;

  --sans:
    "Inter Tight", Inter, "Helvetica Neue", -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  --serif: Didot, "Playfair Display", "Hoefler Text", Georgia, serif;
  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, "DejaVu Sans Mono", Consolas, monospace;

  --gap: 18px;
}

* {
  box-sizing: border-box;
}

:focus-visible {
  outline: 1px solid var(--ember);
  outline-offset: 2px;
}

/* --- shell ------------------------------------------------------------- */

.shell {
  height: 100dvh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  color: var(--text);
  background: var(--ground);
  font-family: var(--sans);
  font-size: 14px;
  letter-spacing: -0.005em;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  padding: 0 26px;
  height: 62px;
  border-bottom: 1px solid var(--line);
}

.wordmark {
  display: flex;
  align-items: center;
  gap: 11px;
}

.wordmark-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--ember);
}

.wordmark span {
  display: grid;
  gap: 1px;
}

.wordmark strong {
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.03em;
}

.wordmark small,
.panel-head span,
.eyebrow,
.evidence-tag,
.code-tag,
.rail-owner,
.counters span,
.verdict dt,
.verdict-pending {
  color: var(--faint);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.counters {
  display: flex;
  gap: 34px;
  margin-left: auto;
}

.counters div {
  display: grid;
  gap: 2px;
  justify-items: end;
}

.counters strong {
  font-family: var(--mono);
  font-size: 17px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.link-pill {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 12px 5px 10px;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  color: var(--dim);
  font-size: 11px;
  letter-spacing: 0.06em;
}

.link-pill i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--crimson);
}

.link-pill[data-linked] i {
  background: var(--jade);
  box-shadow: 0 0 0 3px rgba(69, 185, 141, 0.16);
}

/* --- stage ------------------------------------------------------------- */

.stage {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr) 340px;
  gap: var(--gap);
  padding: var(--gap) 26px 26px;
  min-height: 0;
}

.lane {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-height: 0;
}

.panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 15px 16px 16px;
  background: var(--raise);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.panel-head {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 13px;
}

.panel-head h2 {
  margin: 0;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.panel-head span {
  margin-left: auto;
  text-align: right;
}

.blank {
  margin: 0;
  color: var(--faint);
  font-size: 12.5px;
  line-height: 1.65;
  max-width: 46ch;
}

/* --- fleet ------------------------------------------------------------- */

.fleet {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  min-height: 0;
}

.node {
  display: grid;
  grid-template-columns: 7px 1fr auto;
  align-items: center;
  gap: 3px 10px;
  padding: 11px 2px;
  border-bottom: 1px solid var(--line);
}

.node:last-child {
  border-bottom: 0;
}

.node-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--faint);
}

.node[data-state="alert"] .node-dot {
  background: var(--ember);
  box-shadow: 0 0 0 3px var(--ember-dim);
}

.node[data-state="protected"] .node-dot {
  background: var(--jade);
}

.node[data-state="updating"] .node-dot {
  background: var(--steel);
}

.node[data-state="offline"] .node-dot {
  background: #33373f;
}

.node-id {
  font-family: var(--mono);
  font-size: 13px;
  letter-spacing: -0.02em;
}

.node-state {
  color: var(--faint);
  font-size: 10px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.node[data-state="alert"] .node-state {
  color: var(--ember);
}

.node[data-state="protected"] .node-state {
  color: var(--jade);
}

.node[data-state="updating"] .node-state {
  color: var(--steel);
}

