/* Dark ground, ember for heat, steel for work in progress, jade for cleared.
   Glow is spent only where state changes; the code panel is the hero and
   everything around it stays quiet. */

:root {
  --ground: #0b0c0f;
  --raise: #14161b;
  --sunk: #070809;

  --line: rgba(228, 231, 240, 0.07);
  --line-2: rgba(228, 231, 240, 0.14);

  --text: #e8eaf0;
  --dim: #99a0ae;
  --faint: #666d7b;

  --ember: #e0653a;
  --ember-dim: rgba(224, 101, 58, 0.14);
  --steel: #7fa8c4;
  --jade: #45b98d;
  --crimson: #ef5350;

  --sans:
    "Inter Tight", Inter, "Helvetica Neue", -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  --serif: Didot, "Playfair Display", "Hoefler Text", Georgia, serif;
  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, "DejaVu Sans Mono", Consolas, monospace;

  --gap: 18px;
}

* {
  box-sizing: border-box;
}

:focus-visible {
  outline: 1px solid var(--ember);
  outline-offset: 2px;
}

/* --- shell ------------------------------------------------------------- */

.shell {
  height: 100dvh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  color: var(--text);
  background: var(--ground);
  font-family: var(--sans);
  font-size: 14px;
  letter-spacing: -0.005em;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  padding: 0 26px;
  height: 62px;
  border-bottom: 1px solid var(--line);
}

.wordmark {
  display: flex;
  align-items: center;
  gap: 11px;
}

.wordmark-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--ember);
}

.wordmark span {
  display: grid;
  gap: 1px;
}

.wordmark strong {
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.03em;
}

.wordmark small,
.panel-head span,
.eyebrow,
.evidence-tag,
.code-tag,
.rail-owner,
.counters span,
.verdict dt,
.verdict-pending {
  color: var(--faint);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.counters {
  display: flex;
  gap: 34px;
  margin-left: auto;
}

.counters div {
  display: grid;
  gap: 2px;
  justify-items: end;
}

.counters strong {
  font-family: var(--mono);
  font-size: 17px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.link-pill {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 12px 5px 10px;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  color: var(--dim);
  font-size: 11px;
  letter-spacing: 0.06em;
}

.link-pill i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--crimson);
}

.link-pill[data-linked] i {
  background: var(--jade);
  box-shadow: 0 0 0 3px rgba(69, 185, 141, 0.16);
}

/* --- stage ------------------------------------------------------------- */

.stage {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr) 340px;
  gap: var(--gap);
  padding: var(--gap) 26px 26px;
  min-height: 0;
}

.lane {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  min-height: 0;
}

.panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 15px 16px 16px;
  background: var(--raise);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.panel-head {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 13px;
}

