    const top = (element: Element): number => (element as HTMLElement).offsetTop;
    const reach = top(rows[target]) - top(rows[0]) + (top(rows[target + 1] ?? rows[target]) - top(rows[target]));
    box.scrollTop = reach <= box.clientHeight ? 0 : top(rows[target - 1]) - top(rows[0]);
